package com.nexusdrive.metadata.service;import com.nexusdrive.common.util.AesEncryptionUtil;import java.util.Base64;import javax.crypto.SecretKey;import javax.crypto.spec.SecretKeySpec;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;@Service public class KeyProtectionService{private final SecretKey master;public KeyProtectionService(@Value("${encryption.master-key}")String encoded){byte[] raw;try{raw=Base64.getDecoder().decode(encoded);}catch(IllegalArgumentException e){throw new IllegalArgumentException("encryption.master-key must be Base64",e);}if(raw.length!=32)throw new IllegalArgumentException("encryption.master-key must decode to exactly 32 bytes");master=new SecretKeySpec(raw,"AES");}public String protect(SecretKey dataKey){return "v1:"+Base64.getEncoder().encodeToString(AesEncryptionUtil.encrypt(dataKey.getEncoded(),master));}public SecretKey unprotect(String reference){if(reference==null||!reference.startsWith("v1:"))throw new IllegalArgumentException("Unsupported encryption key reference");byte[] wrapped=Base64.getDecoder().decode(reference.substring(3));return new SecretKeySpec(AesEncryptionUtil.decrypt(wrapped,master),"AES");}}
